import type { SupportedLocale } from "../i18n/types";

/**
 * Formats a monetary amount given in EUR cents to a localized currency string.
 * Uses non-breaking space (U+00A0) for French currency formatting if generated by Intl.
 *
 * Examples:
 *   formatMoney(1250, "en") => "€12.50"
 *   formatMoney(1250, "fr") => "12,50 €"
 */
export function formatMoney(cents: number, locale: SupportedLocale = "en"): string {
  const euros = cents / 100;
  return new Intl.NumberFormat(locale === "fr" ? "fr-FR" : "en-IE", {
    style: "currency",
    currency: "EUR",
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  }).format(euros);
}
